Future<void> _runSignIn({bool validateForm = false, required Future<AuthUser> Function(bool remember) action}) async {
 if (_busy) return;
 setState(() { _errorMessage = null; });
 if (validateForm && !(_formKey.currentState?.validate() ?? false)) return;
 setState(() => _busy = true);
 try {
   final user = await action(_remember);
   TextInput.finishAutofillContext(shouldSavePassword: true); // save credentials where supported
   widget.onAuthenticated?.call(user);
