class DefaultAuthGateway implements AuthGateway {
 bool _googleInitialized = false;

 Future<void> _ensureGoogleInitialized() async {
   if (_googleInitialized) return;
   await GoogleSignIn.instance.initialize();
   _googleInitialized = true;
 }

 @override
 Future<AuthUser> signInWithEmail(String email, String password) async {
   if (!_isValidEmail(email) || password.length < 6) {
     throw const AuthException('Invalid email or password.');
   }
   // No backend is wired in this example: a well-formed credential is
   // accepted locally. Replace with a real identity API call.
   final normalized = email.trim().toLowerCase();
   return AuthUser(id: 'local:$normalized', email: normalized, displayName: normalized.split('@').first, provider: AuthProvider.email);
 }

 @override
 Future<AuthUser> signInWithGoogle() async {
   try {
     await _ensureGoogleInitialized();
     final account = await GoogleSignIn.instance.authenticate();
     return AuthUser(id: account.id, email: account.email, displayName: account.displayName, provider: AuthProvider.google);
   } on GoogleSignInException catch (e) {
     if (e.code == GoogleSignInExceptionCode.canceled) throw AuthCancelledException();
     throw AuthException(e.description ?? 'Google sign-in failed.');
   }
 }

 @override
