  String? _validatePassword(String? value) {
    final password = value ?? '';
    if (password.isEmpty) return 'Enter your password';
    if (!CredentialsValidator.isValidPassword(password)) {
      return 'Password must be at least 6 characters';
    }
    return null;
  }

