          if (user != null) {
            return HomePage(
              user: user,
              authService: _service,
              onSignedOut: _onSignedOut,
            );
          }
          return LoginPage(
            authService: _service,
            appleSignInAvailable: _appleAvailable ?? true,
            onAuthenticated: _onAuthenticated,
          );
        },
      ),
