  Future<AuthUser?> restore() async {
    final prefs = await _prefs;
    final raw = prefs.getString(_key);
    if (raw == null) return null;
    try {
      return AuthUser.fromJson(jsonDecode(raw) as Map<String, Object?>);
    } catch (_) {
      await clear();
      return null;
    }
  }

